    if all(a[i] <= a[i + 1] for i in range(n - 1)):
        return 0, []

    # Find all inversions
    inversions = []
    for i in range(n):
        for j in range(i + 1, n):
            if a[i] > a[j]:
                inversions.append((i + 1, j + 1))

    # Check if we can sort the array using the inversions
